use super::*;
use semio_framework_test_fixtures::fixture_text;
use semio_framework_value::{OriginalRetirementFailure,RetainedCloneGrant,RetainedCloneStep,RetainedWorkOutcome,RetainedWorkPoll};
use semio_framework_value_native_owned::native_decoding::{NativeAllocationEvent,NativeDecodeControl,NativeDecodeProgress,NativeDecodeRetirementRecipient};
use semio_framework_value_testing_admission::{driven,BankWallet,EffectBank};
use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering};

const CLOSE_WORK:u64=1<<20;

/// 🪢️ Runs one decode recipient close turn inside one actual original effect with the heap scope around the owner action only.
fn decode_close(native:&mut NativeDecodeControl<'_>,grant:RetainedCloneGrant)->(RetainedWorkOutcome<RetainedCloneStep,OriginalRetirementFailure>,usize,usize){
 let(poll,born,released)=crate::effect::with_effect(grant,CLOSE_WORK,&mut None,|effect|semio_framework_trace_memory_testing::observe_backing(||native.close_retirement_recipient(grant.maximum_copy_bytes,effect)));
 (crate::effect::settled(poll),born,released)
}
/// 🪢️ Runs one reply-shaped encode recipient close turn under a genuine producer authority with the heap scope around the owner actions only.
fn encode_close(native:&mut semio_framework_value::NativeEncodeControl<'_>,bank:&mut EffectBank,grant:RetainedCloneGrant)->(RetainedWorkOutcome<RetainedCloneStep,OriginalRetirementFailure>,usize,usize){
 let born=std::cell::Cell::new(0usize);let released=std::cell::Cell::new(0usize);
 let(poll,_)=driven::<OriginalRetirementFailure>(bank,grant,CLOSE_WORK,|effect,reply,recover|{let(done,b,r)=semio_framework_trace_memory_testing::observe_backing(||if recover{native.recover_close_retirement_recipient_into(grant.maximum_copy_bytes,effect,reply)}else{native.close_retirement_recipient_into(grant.maximum_copy_bytes,effect,reply)});born.set(born.get()+b);released.set(released.get()+r);done});
 match poll{RetainedWorkPoll::Complete(turn)=>(turn,born.get(),released.get()),RetainedWorkPoll::Pending{..}=>panic!("a driven close settles within its own turns")}
}
/// 🏦️ Seats the finite stock the original encoder caller funds its close turns from.
fn closing_bank(f:&serde_json::Value,grant:RetainedCloneGrant)->EffectBank{EffectBank::new(BankWallet::new(grant,CLOSE_WORK.checked_mul(f["maximumRetirementTurns"].as_u64().unwrap()).unwrap()))}

#[test]
fn sqlite_snapshot_original_physical_final_prefix_has_no_unfunded_release(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../../../🔁️transfer/🫴️receiving/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 let database=SqliteDatabase{tables:vec![SqliteTable{name:law["table"].as_str().unwrap().into(),sql:law["sql"].as_str().unwrap().into(),rows:vec![SqliteRow{rowid:1,values:vec![SqliteValue::Integer(1),SqliteValue::Text(law["text"].as_str().unwrap().into())]}]}]};
 let limits=SqliteDatabaseLimits{max_file_bytes:law["sqlLimits"]["maxFileBytes"].as_u64().unwrap()as usize,max_value_bytes:law["sqlLimits"]["maxValueBytes"].as_u64().unwrap()as usize,max_allocation_bytes:law["sqlLimits"]["maxAllocationBytes"].as_u64().unwrap()as usize,max_schema_bytes:law["sqlLimits"]["maxSchemaBytes"].as_u64().unwrap()as usize,max_rows:law["sqlLimits"]["maxRows"].as_u64().unwrap()as usize,max_columns:law["sqlLimits"]["maxColumns"].as_u64().unwrap()as usize,max_tables:law["sqlLimits"]["maxTables"].as_u64().unwrap()as usize,max_pages:law["sqlLimits"]["maxPages"].as_u64().unwrap()as usize};
 let expected=law["expectedFileBytes"].as_u64().unwrap()as usize;
 let baseline=export_sqlite_database(&database,limits,&mut |_|true).unwrap();assert_eq!(baseline.len(),expected);
 let script="const {Database}=require('bun:sqlite');(async()=>{const chunks=[];for await(const c of process.stdin)chunks.push(c);const db=Database.deserialize(Buffer.concat(chunks));try{console.log(JSON.stringify(db.query('SELECT CAST(id AS TEXT) AS id,text FROM document').get()))}finally{db.close()}})()";
 use std::{io::Write,process::{Command,Stdio}};
 let mut oracle=Command::new("repo").args(["tools","exec","bun","--","--eval",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();oracle.stdin.take().unwrap().write_all(&baseline).unwrap();let observation=oracle.wait_with_output().unwrap();assert!(observation.status.success(),"{}",String::from_utf8_lossy(&observation.stderr));assert_eq!(serde_json::from_slice::<serde_json::Value>(&observation.stdout).unwrap(),serde_json::json!({"id":law["rowid"],"text":law["text"]}));
 let final_birth=AtomicBool::new(false);let owned=AtomicUsize::new(0);let events=AtomicUsize::new(0);let maximum=law["nativeMaximumBytes"].as_u64().unwrap()as usize;
 let allocation=|event:NativeAllocationEvent|{let(NativeAllocationEvent::Admit(request)|NativeAllocationEvent::Quote(request))=event else{return Ok(())};owned.store(request.next_owned_bytes,Ordering::Relaxed);if request.bytes==expected{final_birth.store(true,Ordering::Relaxed)}Ok(())};
 let mut observe=|_:NativeDecodeProgress|{if !final_birth.load(Ordering::Relaxed){return true}events.fetch_add(1,Ordering::Relaxed);events.load(Ordering::Relaxed)<law["cancelFinalCheckpoint"].as_u64().unwrap()as usize};
 let mut recipient=NativeDecodeRetirementRecipient::new();let grant:RetainedCloneGrant=serde_json::from_value(law["originalGrant"].clone()).unwrap();let prefix=AtomicUsize::new(0);
 crate::with_allocation_port(allocation,|loan|{
  let mut native=NativeDecodeControl::new_forwarded(maximum,&mut observe,loan);native.install_retirement_recipient(&mut recipient).unwrap();let mut published:Option<()>=None;
  let(result,born,released)=crate::with_original_authorities(grant,|work,construction|native.with_work_recipient(work,|native|native.with_construction_recipient(construction,|native|{
   let mut owner=crate::original_control::NativeSnapshotDecodeOwner::new(native,grant);
   let observed=semio_framework_trace_memory_testing::observe_backing(||owner.receive::<PhysicalExportFrame,(),ValueError>(&mut published,&mut |slot,output,_marker,_failure,native,body|{*slot=Some(PhysicalExportFrame::new());let mut progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut progress,limits);let result=(||{let mut port=artifact::receiving::Port{control:&mut control,native:artifact::receiving::Direction::Decode(native),body};let result=export_sqlite_database_receiving_into(&database,slot.as_mut().unwrap(),&mut port);prefix.store(slot.as_ref().unwrap().output.len(),Ordering::Relaxed);result})();if result.is_ok(){*output=Some(())}semio_framework_value::RetainedWorkOutcome{work:u128::from(control.performed_work()),result}}));
   drop(owner);Ok::<_,ValueError>(observed)
  })));
  let work=result.work;let error=result.result.unwrap_err();assert!(work>0);assert_eq!(prefix.load(Ordering::Relaxed),law["expectedRefusedPrefixBytes"].as_u64().unwrap()as usize);assert_eq!(error.kind().as_str(),law["expectedRefusalKind"].as_str().unwrap());assert_eq!(error.message(),law["expectedDirectNativeRefusalMessage"].as_str().unwrap());assert!(final_birth.load(Ordering::Relaxed));assert!(events.load(Ordering::Relaxed)>=law["cancelFinalCheckpoint"].as_u64().unwrap()as usize);assert!(born>=expected+law["pageBytes"].as_u64().unwrap()as usize);
  assert_eq!(released,law["expectedRefusedReleasedBytes"].as_u64().unwrap()as usize,"refused final output and every writer scratch owner must remain in original funded custody");assert!(native.has_retirement_owner());
  final_birth.store(false,Ordering::Relaxed);
  let(zero_poll,zero_born,zero_released)=crate::effect::with_effect(RetainedCloneGrant::default(),CLOSE_WORK,&mut None,|effect|semio_framework_trace_memory_testing::observe_backing(||native.close_retirement_recipient(0,effect)));
  match zero_poll{RetainedWorkPoll::Pending{work}=>assert_eq!(work,0),RetainedWorkPoll::Complete(turn)=>{assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default())}}assert_eq!((zero_born,zero_released),(0,0));
  let mut cleanup_born=0;let mut cleanup_released=0;let mut retirement_work=0u128;for _ in 0..law["maximumRetirementTurns"].as_u64().unwrap(){if !native.has_retirement_owner(){break}let(turn,b,r)=decode_close(&mut native,grant);retirement_work+=turn.work;let step=turn.result.unwrap();assert_eq!((b,r),(step.progress().retained_capacity_bytes,step.progress().released_bytes));cleanup_born+=b;cleanup_released+=r;}assert!(!native.has_retirement_owner());assert!(retirement_work>0);assert_eq!(cleanup_released,born+cleanup_born);
 });
}

fn original_fixture()->serde_json::Value{serde_json::from_str(fixture_text!("../../../../🔁️transfer/🫴️receiving/🧪️tests/🧫️fixtures/🔣️.json")).unwrap()}
fn original_limits(f:&serde_json::Value)->SqliteDatabaseLimits{let p=&f["sqlLimits"];SqliteDatabaseLimits{max_file_bytes:p["maxFileBytes"].as_u64().unwrap()as usize,max_value_bytes:p["maxValueBytes"].as_u64().unwrap()as usize,max_allocation_bytes:p["maxAllocationBytes"].as_u64().unwrap()as usize,max_schema_bytes:p["maxSchemaBytes"].as_u64().unwrap()as usize,max_rows:p["maxRows"].as_u64().unwrap()as usize,max_columns:p["maxColumns"].as_u64().unwrap()as usize,max_tables:p["maxTables"].as_u64().unwrap()as usize,max_pages:p["maxPages"].as_u64().unwrap()as usize}}
fn original_database(f:&serde_json::Value)->SqliteDatabase{SqliteDatabase{tables:vec![SqliteTable{name:f["table"].as_str().unwrap().into(),sql:f["sql"].as_str().unwrap().into(),rows:vec![SqliteRow{rowid:1,values:vec![SqliteValue::Integer(1),SqliteValue::Text(f["text"].as_str().unwrap().into())]}]}]}}
#[test]
fn sqlite_snapshot_original_physical_empty_frames_allocate_nothing(){let((export,import),born,released)=semio_framework_trace_memory_testing::observe_backing(||(PhysicalExportFrame::new(),PhysicalImportFrame::new()));assert_eq!((born,released),(0,0));assert!(export.output.is_empty());assert!(import.database.tables.is_empty());assert_eq!(semio_framework_trace_memory_testing::observe_backing(||drop((export,import))),((),0,0));}
#[test]
fn sqlite_snapshot_original_physical_success_uses_both_real_owners_and_exact_funded_scratch(){
 let f=original_fixture();let limits=original_limits(&f);let database=original_database(&f);let grant:semio_framework_value::RetainedCloneGrant=serde_json::from_value(f["originalGrant"].clone()).unwrap();let maximum=f["nativeMaximumBytes"].as_u64().unwrap()as usize;
 let mut decode_progress=|_|true;let mut decode_recipient=NativeDecodeRetirementRecipient::new();let mut decode=NativeDecodeControl::new(maximum,&mut decode_progress);decode.install_retirement_recipient(&mut decode_recipient).unwrap();let mut published:Option<Vec<u8>>=None;
 let(exported,born,released,decoded)=crate::with_original_authorities(grant,|work,construction|decode.with_work_recipient(work,|native|native.with_construction_recipient(construction,|native|{
  let mut decoder=crate::original_control::NativeSnapshotDecodeOwner::new(native,grant);
  let(exported,born,released)=semio_framework_trace_memory_testing::observe_backing(||decoder.receive::<PhysicalExportFrame,Vec<u8>,ValueError>(&mut published,&mut |slot,output,_marker,_failure,native,body|{*slot=Some(PhysicalExportFrame::new());let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,limits);let result=(||{let mut port=artifact::receiving::Port{control:&mut control,native:artifact::receiving::Direction::Decode(native),body};export_sqlite_database_receiving_into(&database,slot.as_mut().unwrap(),&mut port)?;port.work(1,std::mem::size_of::<Vec<u8>>())?;*output=Some(std::mem::take(&mut slot.as_mut().unwrap().output));Ok(())})();semio_framework_value::RetainedWorkOutcome{work:u128::from(control.performed_work()),result}}));
  let decoded=decoder.progress();drop(decoder);Ok::<_,ValueError>((exported,born,released,decoded))
 })));
 assert!(exported.work>0);exported.result.unwrap();let file=published.take().unwrap();assert_eq!(file.len(),f["expectedFileBytes"].as_u64().unwrap()as usize);assert_eq!(born,released+file.capacity());assert_eq!(decoded.retained_capacity_bytes,born);assert_eq!(decoded.released_bytes,released);assert!(!decode.has_retirement_owner());assert_eq!(import_sqlite_database(&file,limits,&mut |_|true).unwrap(),database);
 use std::{io::Write,process::{Command,Stdio}};let script="const {Database}=require('bun:sqlite');(async()=>{const chunks=[];for await(const c of process.stdin)chunks.push(c);const db=Database.deserialize(Buffer.concat(chunks));try{console.log(JSON.stringify({row:db.query('SELECT CAST(id AS TEXT) AS id,text FROM document').get(),integrity:db.query('PRAGMA integrity_check').get()}))}finally{db.close()}})()";let mut oracle=Command::new("repo").args(["tools","exec","bun","--","--eval",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();oracle.stdin.take().unwrap().write_all(&file).unwrap();let observation=oracle.wait_with_output().unwrap();assert!(observation.status.success(),"{}",String::from_utf8_lossy(&observation.stderr));assert_eq!(serde_json::from_slice::<serde_json::Value>(&observation.stdout).unwrap(),serde_json::json!({"row":{"id":f["rowid"],"text":f["text"]},"integrity":{"integrity_check":"ok"}}));
 let mut encode_progress=|_|true;let mut encode_recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let mut encode=semio_framework_value::NativeEncodeControl::new(maximum,&mut encode_progress);encode.install_retirement_recipient(&mut encode_recipient).unwrap();let mut imported_database:Option<SqliteDatabase>=None;
 let(imported,import_born,import_released,encoded)=crate::with_original_authorities(grant,|work,construction|encode.with_work_recipient(work,|native|native.with_construction_recipient(construction,|native|{
  let mut encoder=crate::original_control::NativeSnapshotEncodeOwner::new(native,grant);
  let(imported,import_born,import_released)=semio_framework_trace_memory_testing::observe_backing(||encoder.receive::<PhysicalImportFrame,SqliteDatabase,ValueError>(&mut imported_database,&mut |slot,output,_marker,_failure,native,body|{*slot=Some(PhysicalImportFrame::new());let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,limits);let result=(||{let mut port=artifact::receiving::Port{control:&mut control,native:artifact::receiving::Direction::Encode(native),body};import_sqlite_database_receiving_into(&file,slot.as_mut().unwrap(),&mut port)?;port.work(1,std::mem::size_of::<SqliteDatabase>())?;*output=Some(std::mem::replace(&mut slot.as_mut().unwrap().database,SqliteDatabase{tables:Vec::new()}));Ok(())})();semio_framework_value::RetainedWorkOutcome{work:u128::from(control.performed_work()),result}}));
  let encoded=encoder.progress();drop(encoder);Ok::<_,ValueError>((imported,import_born,import_released,encoded))
 })));
 assert!(imported.work>0);imported.result.unwrap();let actual=imported_database.take().unwrap();assert_eq!(actual,database);assert_eq!(encoded.retained_capacity_bytes,import_born);assert_eq!(encoded.released_bytes,import_released);assert!(!encode.has_retirement_owner());let(_,_,output_backing)=semio_framework_trace_memory_testing::observe_backing(||drop(actual));assert_eq!(import_born,import_released+output_backing);
}

#[test]
fn sqlite_snapshot_original_physical_parser_canceled_text_prefix_remains_with_original_encoder(){
 let f=original_fixture();let database=original_database(&f);let limits=original_limits(&f);let file=export_sqlite_database(&database,limits,&mut |_|true).unwrap();let text=f["text"].as_str().unwrap();let maximum=f["nativeMaximumBytes"].as_u64().unwrap()as usize;let grant:semio_framework_value::RetainedCloneGrant=serde_json::from_value(f["originalGrant"].clone()).unwrap();let live=AtomicBool::new(true);let copied=AtomicBool::new(false);let mut progress=|event:semio_framework_value::native_encoding::NativeEncodeProgress|{if event.total==text.len()&&event.completed==text.len(){copied.store(true,Ordering::Relaxed);live.store(false,Ordering::Relaxed)}live.load(Ordering::Relaxed)};let mut recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let mut native=semio_framework_value::NativeEncodeControl::new(maximum,&mut progress);native.install_retirement_recipient(&mut recipient).unwrap();let mut published:Option<()>=None;
 let(result,born,released,performed)=crate::with_original_authorities(grant,|work,construction|native.with_work_recipient(work,|native|native.with_construction_recipient(construction,|native|{
  let mut owner=crate::original_control::NativeSnapshotEncodeOwner::new(native,grant);
  let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||owner.receive::<PhysicalImportFrame,(),ValueError>(&mut published,&mut |slot,output,_marker,_failure,native,body|{*slot=Some(PhysicalImportFrame::new());let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,limits);let result=(||{let mut port=artifact::receiving::Port{control:&mut control,native:artifact::receiving::Direction::Encode(native),body};import_sqlite_database_receiving_into(&file,slot.as_mut().unwrap(),&mut port)})();if result.is_ok(){*output=Some(())}semio_framework_value::RetainedWorkOutcome{work:u128::from(control.performed_work()),result}}));
  let performed=owner.progress();drop(owner);Ok::<_,ValueError>((result,born,released,performed))
 })));
 let work=result.work;let error=result.result.unwrap_err();assert!(work>0);assert_eq!(error.kind(),ValueRefusalKind::Canceled);assert_eq!(error.message(),f["expectedEncoderRefusalMessage"].as_str().unwrap());assert!(copied.load(Ordering::Relaxed));assert_eq!(released,0);assert_eq!(performed.retained_capacity_bytes,born);assert!(native.has_retirement_owner());live.store(true,Ordering::Relaxed);
 let mut bank=closing_bank(&f,grant);let mut extra=0;let mut retired=0;let mut retirement_work=0u128;for _ in 0..f["maximumRetirementTurns"].as_u64().unwrap(){if !native.has_retirement_owner(){break}let(turn,b,r)=encode_close(&mut native,&mut bank,grant);retirement_work+=turn.work;let step=turn.result.unwrap();assert_eq!((b,r),(step.progress().retained_capacity_bytes,step.progress().released_bytes));extra+=b;retired+=r;}assert!(!native.has_retirement_owner());assert!(retirement_work>0);assert_eq!(retired,born+extra);
}

#[test]
fn sqlite_snapshot_original_physical_overflow_tree_preserves_all_cells_against_independent_sqlite(){
 let f=original_fixture();let forest=&f["forest"];let limits=original_limits(&f);let grant:semio_framework_value::RetainedCloneGrant=serde_json::from_value(f["originalGrant"].clone()).unwrap();let maximum=f["nativeMaximumBytes"].as_u64().unwrap()as usize;let first=forest["firstRowId"].as_i64().unwrap();let seed=forest["textSeed"].as_str().unwrap();let blob=forest["blob"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect::<Vec<_>>();let mut expected=Vec::new();let mut rows=Vec::new();
 for i in 0..forest["rows"].as_u64().unwrap(){let rowid=first+i as i64;let repeats=if i==0{forest["firstTextRepeats"].as_u64().unwrap()}else{forest["otherTextRepeats"].as_u64().unwrap()}as usize;let text=seed.repeat(repeats);expected.push(serde_json::json!({"id":rowid.to_string(),"blobHex":"0001FF80","kind":"real","value":forest["real"],"textBytes":text.len()}));rows.push(SqliteRow{rowid,values:vec![SqliteValue::Integer(rowid),SqliteValue::Text(text),SqliteValue::Blob(blob.clone()),SqliteValue::Real(forest["real"].as_f64().unwrap())]});}assert_eq!(rows.last().unwrap().rowid,forest["lastRowId"].as_i64().unwrap());let database=SqliteDatabase{tables:vec![SqliteTable{name:forest["table"].as_str().unwrap().into(),sql:forest["sql"].as_str().unwrap().into(),rows}]};
 let mut progress=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut native=NativeDecodeControl::new(maximum,&mut progress);native.install_retirement_recipient(&mut recipient).unwrap();let mut published:Option<Vec<u8>>=None;
 let(result,born,released,decoded)=crate::with_original_authorities(grant,|work,construction|native.with_work_recipient(work,|native|native.with_construction_recipient(construction,|native|{
  let mut owner=crate::original_control::NativeSnapshotDecodeOwner::new(native,grant);
  let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||owner.receive::<PhysicalExportFrame,Vec<u8>,ValueError>(&mut published,&mut |slot,output,_marker,_failure,native,body|{*slot=Some(PhysicalExportFrame::new());let mut progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut progress,limits);let result=(||{let mut port=artifact::receiving::Port{control:&mut control,native:artifact::receiving::Direction::Decode(native),body};export_sqlite_database_receiving_into(&database,slot.as_mut().unwrap(),&mut port)?;port.work(1,std::mem::size_of::<Vec<u8>>())?;*output=Some(std::mem::take(&mut slot.as_mut().unwrap().output));Ok(())})();semio_framework_value::RetainedWorkOutcome{work:u128::from(control.performed_work()),result}}));
  let decoded=owner.progress();drop(owner);Ok::<_,ValueError>((result,born,released,decoded))
 })));
 assert!(result.work>0);result.result.unwrap();let file=published.take().unwrap();assert!(file.len()>3*f["pageBytes"].as_u64().unwrap()as usize);assert_eq!(file.len()%f["pageBytes"].as_u64().unwrap()as usize,0);assert_eq!(born,released+file.capacity());assert_eq!((decoded.retained_capacity_bytes,decoded.released_bytes),(born,released));assert!(!native.has_retirement_owner());
 use std::{io::Write,process::{Command,Stdio}};let script="const {Database}=require('bun:sqlite');(async()=>{const chunks=[];for await(const c of process.stdin)chunks.push(c);const db=Database.deserialize(Buffer.concat(chunks));try{console.log(JSON.stringify({rows:db.query('SELECT CAST(id AS TEXT) AS id,hex(blob) AS blobHex,typeof(value) AS kind,value,length(CAST(text AS BLOB)) AS textBytes FROM payload ORDER BY payload.id').all(),integrity:db.query('PRAGMA integrity_check').get()}))}finally{db.close()}})()";let mut oracle=Command::new("repo").args(["tools","exec","bun","--","--eval",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();oracle.stdin.take().unwrap().write_all(&file).unwrap();let observation=oracle.wait_with_output().unwrap();assert!(observation.status.success(),"{}",String::from_utf8_lossy(&observation.stderr));assert_eq!(serde_json::from_slice::<serde_json::Value>(&observation.stdout).unwrap(),serde_json::json!({"rows":expected,"integrity":{"integrity_check":"ok"}}));
 let mut progress=|_|true;let mut recipient=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let mut native=semio_framework_value::NativeEncodeControl::new(maximum,&mut progress);native.install_retirement_recipient(&mut recipient).unwrap();let mut imported_database:Option<SqliteDatabase>=None;
 let(result,born,released,encoded)=crate::with_original_authorities(grant,|work,construction|native.with_work_recipient(work,|native|native.with_construction_recipient(construction,|native|{
  let mut owner=crate::original_control::NativeSnapshotEncodeOwner::new(native,grant);
  let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||owner.receive::<PhysicalImportFrame,SqliteDatabase,ValueError>(&mut imported_database,&mut |slot,output,_marker,_failure,native,body|{*slot=Some(PhysicalImportFrame::new());let mut progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut progress,limits);let result=(||{let mut port=artifact::receiving::Port{control:&mut control,native:artifact::receiving::Direction::Encode(native),body};import_sqlite_database_receiving_into(&file,slot.as_mut().unwrap(),&mut port)?;port.work(1,std::mem::size_of::<SqliteDatabase>())?;*output=Some(std::mem::replace(&mut slot.as_mut().unwrap().database,SqliteDatabase{tables:Vec::new()}));Ok(())})();semio_framework_value::RetainedWorkOutcome{work:u128::from(control.performed_work()),result}}));
  let encoded=owner.progress();drop(owner);Ok::<_,ValueError>((result,born,released,encoded))
 })));
 assert!(result.work>0);result.result.unwrap();let actual=imported_database.take().unwrap();assert_eq!(actual,database);assert_eq!((encoded.retained_capacity_bytes,encoded.released_bytes),(born,released));assert!(!native.has_retirement_owner());let(_,_,output_backing)=semio_framework_trace_memory_testing::observe_backing(||drop(actual));assert_eq!(born,released+output_backing);
}
